import{_ as a,o as t,c as r,ak as i}from"./chunks/framework.Cq0X4QeM.js";const d=JSON.parse('{"title":"Lateral movement","description":"","frontmatter":{"authors":"BlWasp, ShutdownRepo, felixbillieres","category":"ad"},"headers":[],"relativePath":"ad/movement/sccm-mecm/lateral-movement/index.md","filePath":"ad/movement/sccm-mecm/lateral-movement/index.md"}'),o={name:"ad/movement/sccm-mecm/lateral-movement/index.md"};function n(s,e,c,h,l,m){return t(),r("div",null,e[0]||(e[0]=[i('<h1 id="lateral-movement" tabindex="-1">Lateral movement <a class="header-anchor" href="#lateral-movement" aria-label="Permalink to &quot;Lateral movement&quot;">​</a></h1><h2 id="theory" tabindex="-1">Theory <a class="header-anchor" href="#theory" aria-label="Permalink to &quot;Theory&quot;">​</a></h2><p>Since the main goal of SCCM is to deploy applications and services on the managed assets of the Active Directory, it is also a pretty good candidate to move latteraly on the network. With administrative rights on the primary site server, this can be done by deploying applications and scripts on the targets or coercing clients&#39; authentication.</p><p>Additionally, SCCM permits to enumerate many data on the ressources. Among all the services offered by SCCM to the administrator, there is one named CMPivot. This service, located on the MP server, can enumerate all the resources of a computer or computer collection (installed software, local administrators, hardware specification, etc.), and perform administrative tasks on them. It uses a HTTP REST API, named AdminService, provided by the SMS Provider server.</p><p>Finally, as indicated by <a href="https://mobile.twitter.com/_mayyhem" target="_blank" rel="noreferrer">Chris Thompson</a> in his article <a href="https://posts.specterops.io/sccm-hierarchy-takeover-41929c61e087" target="_blank" rel="noreferrer">SCCM Hierarchy Takeover</a>, by default, when a new user is promoted to any SCCM administrative role on a primary site server (for example, <code>Full Administrator</code>), the role is automatically propagated to the other SCCM site in the hierarchy by the CAS.</p><p>This means that there is no security boundary between SCCM sites in a same hierarchy, and being able to takeover one SCCM site implicates to takeover all the others.</p><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><h3 id="admin-special-account-enumeration" tabindex="-1">Admin &amp; Special Account Enumeration <a class="header-anchor" href="#admin-special-account-enumeration" aria-label="Permalink to &quot;Admin &amp; Special Account Enumeration&quot;">​</a></h3><p>Administrative privileges over the SCCM Management Point (MP) are required to query the MP&#39;s WMI database for admin and special accounts.</p><div class="tip custom-block"><p>Read the <a href="./enumeration">enumeration</a> article for detailed information on enumerating admin and special accounts.</p></div><h3 id="applications-and-scripts-deployment" tabindex="-1">Applications and scripts deployment <a class="header-anchor" href="#applications-and-scripts-deployment" aria-label="Permalink to &quot;Applications and scripts deployment&quot;">​</a></h3><p>With administrative rights on the primary site server, applications and scripts can be deployed on target devices to move laterally across the network.</p><div class="tip custom-block"><p>Read the <a href="./deployment">deployment</a> article for detailed information on deploying applications and scripts via SCCM.</p></div><h3 id="adminservice-api" tabindex="-1">AdminService API <a class="header-anchor" href="#adminservice-api" aria-label="Permalink to &quot;AdminService API&quot;">​</a></h3><p>The AdminService API can be used to interact directly with SCCM resources for post-exploitation purposes, without using CMPivot.</p><div class="tip custom-block"><p>Read the <a href="./adminservice-api">AdminService API</a> article for detailed information on using the AdminService API.</p></div><h3 id="sccm-hierarchy-takeover" tabindex="-1">SCCM Hierarchy takeover <a class="header-anchor" href="#sccm-hierarchy-takeover" aria-label="Permalink to &quot;SCCM Hierarchy takeover&quot;">​</a></h3><p>By default, when a new user is promoted to any SCCM administrative role on a primary site server, the role is automatically propagated to the other SCCM site in the hierarchy by the CAS.</p><div class="tip custom-block"><p>Read the <a href="./hierarchy-takeover">hierarchy takeover</a> article for detailed information on SCCM hierarchy takeover.</p></div><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><p><a href="https://www.securesystems.de/blog/active-directory-spotlight-attacking-the-microsoft-configuration-manager/" target="_blank" rel="noreferrer">https://www.securesystems.de/blog/active-directory-spotlight-attacking-the-microsoft-configuration-manager/</a></p><p><a href="https://enigma0x3.net/2016/02/" target="_blank" rel="noreferrer">https://enigma0x3.net/2016/02/</a></p><p><a href="https://posts.specterops.io/sccm-hierarchy-takeover-41929c61e087" target="_blank" rel="noreferrer">https://posts.specterops.io/sccm-hierarchy-takeover-41929c61e087</a></p><p><a href="https://github.com/subat0mik/Misconfiguration-Manager/tree/main/attack-techniques/EXEC" target="_blank" rel="noreferrer">https://github.com/subat0mik/Misconfiguration-Manager/tree/main/attack-techniques/EXEC</a></p><p><a href="https://github.com/subat0mik/Misconfiguration-Manager/tree/main/attack-techniques/RECON" target="_blank" rel="noreferrer">https://github.com/subat0mik/Misconfiguration-Manager/tree/main/attack-techniques/RECON</a></p><p><a href="https://github.com/subat0mik/Misconfiguration-Manager/tree/main/attack-techniques/TAKEOVER" target="_blank" rel="noreferrer">https://github.com/subat0mik/Misconfiguration-Manager/tree/main/attack-techniques/TAKEOVER</a></p>',26)]))}const u=a(o,[["render",n]]);export{d as __pageData,u as default};
